//   +0x160 copy<pathCell*> (0x5093c0)  - result.clear()
//   +0x182 copy<pathCell>  (0x4b4270)  - queue.clear()
//   +0x218 copy<pathCell>  (0x4b4270)  - queue.pop_back()
